<?php
require_once __DIR__.'/includes/functions.php';
$page = $_GET['page'] ?? 'home';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    try {
        verify_csrf();
        if ($action === 'login') {
            $id=trim($_POST['identifier'] ?? ''); $pw=(string)($_POST['password'] ?? '');
            $q=db()->prepare('SELECT id,identifier,full_name,password_hash,role FROM users WHERE identifier=? LIMIT 1'); $q->execute([$id]); $u=$q->fetch();
            if ($u && password_verify($pw,$u['password_hash'])) { session_regenerate_id(true); unset($u['password_hash']); $_SESSION['user']=$u; flash('Berhasil masuk.'); redirect(in_array($u['role'], ['admin','superadmin'], true) ? 'admin.php' : 'index.php'); }
            flash('ID/NIS/NIP atau kata sandi tidak sesuai.','error'); redirect('index.php?page=login');
        }
        if ($action === 'logout') { $_SESSION=[]; if (ini_get('session.use_cookies')) { $p=session_get_cookie_params(); setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']); } session_destroy(); session_start(); flash('Anda telah logout.'); redirect('index.php'); }
        if ($action === 'vote') {
            $u=current_user(); if (!$u || !in_array($u['role'],['student','employee'],true)) throw new RuntimeException('Silakan login sebagai pemilih terlebih dahulu.');
            if (election_status() !== 'active') throw new RuntimeException('Pemilihan belum dimulai atau sudah berakhir.');
            $cid=(int)($_POST['candidate_id'] ?? 0); $pdo=db(); $pdo->beginTransaction();
            $check=$pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE'); $check->execute([$u['id']]);
            $v=$pdo->prepare('SELECT id FROM votes WHERE user_id=?'); $v->execute([$u['id']]);
            $c=$pdo->prepare('SELECT id FROM candidates WHERE id=?'); $c->execute([$cid]);
            if ($v->fetch()) throw new RuntimeException('Akun ini sudah menggunakan hak suara.');
            if (!$c->fetch()) throw new RuntimeException('Kandidat tidak ditemukan.');
            $ins=$pdo->prepare('INSERT INTO votes(user_id,candidate_id) VALUES(?,?)'); $ins->execute([$u['id'],$cid]);
            $pdo->prepare('UPDATE users SET has_voted=1 WHERE id=?')->execute([$u['id']]); $pdo->commit(); flash('Suara berhasil disimpan. Terima kasih telah berpartisipasi.'); redirect('index.php');
        }
    } catch (Throwable $t) { if (isset($pdo) && $pdo instanceof PDO && $pdo->inTransaction()) $pdo->rollBack(); flash($t instanceof PDOException ? 'Terjadi kesalahan penyimpanan. Periksa data dan konfigurasi database.' : $t->getMessage(),'error'); redirect('index.php?page='.($page==='home'?'home':$page)); }
}
$user=current_user(); $flash=get_flash();
$status='upcoming'; try {$status=election_status();} catch(Throwable $t) {}
$bgIndex=max(1,min(3,(int)setting('active_background','1'))); $bg=setting('background_'.$bgIndex,'assets/bg-school.svg');
$candidates=[]; try {$candidates=db()->query('SELECT * FROM candidates ORDER BY candidate_number,id')->fetchAll();} catch(Throwable $t) {}
$votesByCandidate=[]; $totalVotes=0; try { foreach(db()->query('SELECT candidate_id,COUNT(*) total FROM votes GROUP BY candidate_id') as $r){$votesByCandidate[$r['candidate_id']]=(int)$r['total'];$totalVotes+=(int)$r['total'];} } catch(Throwable $t) {}
function nav_active(string $p,string $current): string { return $p===$current?'active':''; }
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e(setting('school_name','WeVote'))?> · WeVote</title><link rel="stylesheet" href="assets/style.css"></head>
<body class="<?=e(($_SESSION['theme']??'light'))?>" style="--hero-bg:url('<?=e($bg)?>')"><div class="bg-overlay"></div>
<header class="site-header"><a class="brand" href="index.php"><span class="brand-logo"><?php if(setting('school_logo')): ?><img src="<?=e(setting('school_logo'))?>" alt="Logo sekolah"><?php else: ?><span>W</span><?php endif; ?></span><span><b><?=e(setting('school_name','SMK Negeri'))?></b><small>Digital Election</small></span></a><nav><a class="<?=nav_active('home',$page)?>" href="index.php">Home</a><a href="index.php?page=vision">Visi Misi Sekolah</a><a href="index.php?page=about">About</a><a href="index.php?page=contact">Contact</a></nav><div class="header-actions"><?php if($user): ?><span class="user-chip"><?=e($user['full_name'])?></span><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="logout"><button class="btn btn-primary" type="submit">Logout</button></form><?php else: ?><a class="btn btn-primary" href="index.php?page=login">Login Pemilih</a><?php endif; ?></div></header>
<?php if($flash): ?><div class="flash-wrap"><div class="flash <?=e($flash['type'])?>"><?=e($flash['message'])?></div></div><?php endif; ?>
<main>
<?php if($page==='home'): ?>
<section class="hero" id="top"><div class="hero-content"><span class="eyebrow"><?=e(setting('election_type','Pemilihan Sekolah'))?></span><h1>Suaramu,<br><span>Masa Depan Kita.</span></h1><p class="hero-school"><?=e(setting('school_name',''))?></p><div class="election-meta"><span>⌖ <?=e(setting('election_location','Lokasi belum diatur'))?></span><span>◷ <?=e(date('d M Y · H:i',strtotime((string)setting('start_at',date('Y-m-d H:i:s')))))?></span><span>◷ Durasi <?=e(setting('duration_minutes','60'))?> menit</span></div><div class="countdown-card"><span class="countdown-label"><?php if($status==='upcoming') echo 'PEMILIHAN DIMULAI PADA'; elseif($status==='active') echo 'PEMILIHAN SEDANG BERLANGSUNG'; else echo 'PEMILIHAN TELAH BERAKHIR'; ?></span><strong><?php if($status==='upcoming') echo e(date('d M Y, H:i',strtotime((string)setting('start_at')))); elseif($status==='active') echo 'Saatnya menentukan pilihan'; else echo 'Terima kasih atas partisipasi Anda'; ?></strong><small><?php if($status==='upcoming') echo 'Countdown akan diperbarui saat halaman dimuat ulang.'; elseif($status==='active') echo 'Silakan kenali kandidat dan gunakan hak suara Anda.'; else echo 'Hasil pemilihan tersedia di bawah.'; ?></small></div><a class="scroll-cue" href="#kandidat">Lihat kandidat <span>↓</span></a></div></section>
<section class="candidate-section" id="kandidat"><div class="section-heading"><span class="eyebrow">CALON PEMIMPIN</span><h2>Daftar Kandidat</h2><p>Kenali kandidat dan visi misi sebelum menentukan pilihan.</p></div><?php if(!$candidates): ?><p class="empty-state">Belum ada kandidat yang ditambahkan.</p><?php else: ?><div class="candidate-grid"><?php foreach($candidates as $c): ?><article class="candidate-card"><div class="candidate-photo"><img src="<?=e(image_url((string)($c['photo'] ?? '')))?>" alt="Foto <?=e($c['name'])?>"></div><div class="candidate-info"><span class="candidate-number">KANDIDAT <?=e($c['candidate_number'])?></span><h3><?=e($c['name'])?></h3><p class="vision-preview"><?=e(mb_strimwidth($c['vision'],0,115,'…','UTF-8'))?></p><details><summary>Lihat visi &amp; misi</summary><h4>Visi</h4><p><?=nl2br(e($c['vision']))?></p><h4>Misi</h4><p><?=nl2br(e($c['mission']))?></p></details><?php if($status==='active' && $user && in_array($user['role'],['student','employee'],true)): ?><?php if(has_voted((int)$user['id'])): ?><span class="voted-note">✓ Suara telah diberikan</span><?php else: ?><form method="post" class="vote-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="vote"><input type="hidden" name="candidate_id" value="<?=e($c['id'])?>"><button class="btn btn-primary btn-block" type="submit">Pilih Kandidat</button></form><?php endif; ?><?php elseif($status==='active' && !$user): ?><a class="btn btn-outline btn-block" href="index.php?page=login">Login untuk memilih</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
<?php if($status==='finished' && setting('results_public','1')==='1'): ?><section class="results-section"><div class="section-heading"><span class="eyebrow">REKAPITULASI</span><h2>Hasil Pemilihan</h2><p>Total suara masuk: <?=e($totalVotes)?></p></div><div class="result-list"><?php foreach($candidates as $c): $n=$votesByCandidate[$c['id']]??0; $pct=$totalVotes?round($n/$totalVotes*100,1):0; ?><div class="result-row"><div class="result-label"><b><?=e($c['name'])?></b><span><?=e($n)?> suara · <?=e($pct)?>%</span></div><div class="result-track"><span style="width:<?=e($pct)?>%"></span></div></div><?php endforeach; ?></div></section><?php endif; ?>
<?php elseif($page==='login' || $page==='admin-login'): ?><section class="auth-section"><div class="auth-card"><span class="eyebrow"><?= $page==='admin-login'?'AREA ADMIN':'AKSES PEMILIH' ?></span><h1><?= $page==='admin-login'?'Login Admin':'Selamat Datang' ?></h1><p>Masuk menggunakan NIS/NIP atau ID akun yang terdaftar.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="login"><label>ID / NIS / NIP<input name="identifier" required autocomplete="username"></label><label>Kata sandi<input type="password" name="password" required autocomplete="current-password"></label><button class="btn btn-primary btn-block" type="submit">Masuk</button></form><a class="back-link" href="index.php">← Kembali ke halaman utama</a></div></section>
<?php elseif($page==='vision'): ?><section class="simple-page"><span class="eyebrow">TENTANG SEKOLAH</span><h1>Visi &amp; Misi Sekolah</h1><div class="content-panel"><h2>Visi</h2><p><?=nl2br(e(setting('school_vision','Visi sekolah belum diatur.')))?></p><h2>Misi</h2><p><?=nl2br(e(setting('school_mission','Misi sekolah belum diatur.')))?></p></div></section>
<?php elseif($page==='about'): ?><section class="simple-page"><span class="eyebrow">TENTANG APLIKASI</span><h1>About WeVote</h1><div class="content-panel"><p><?=nl2br(e(setting('about_text','Aplikasi pemilihan digital sekolah.')))?></p></div></section>
<?php elseif($page==='contact'): ?><section class="simple-page"><span class="eyebrow">HUBUNGI KAMI</span><h1>Contact</h1><div class="content-panel"><p><?=nl2br(e(setting('contact_text','Hubungi pihak sekolah.')))?></p></div></section>
<?php else: ?><section class="simple-page"><h1>Halaman tidak ditemukan</h1><a class="btn btn-primary" href="index.php">Kembali ke Home</a></section><?php endif; ?>
</main><footer class="site-footer"><b>WeVote!</b><span>Pemilihan yang tertib, aman, dan transparan.</span><a href="index.php?page=admin-login">Admin</a></footer></body></html>
